 62	import jakarta.persistence.*;
 63	import lombok.AllArgsConstructor;
 64	import lombok.Builder;
 65	import lombok.Getter;
 66	import lombok.NoArgsConstructor;
 67	
 68	import java.util.ArrayList;
 69	import java.util.List;
 70	
 71	/**
 72	 * 주문 엔티티
 73	 */
 74	@Entity
 75	@Getter
 76	@NoArgsConstructor
 77	@AllArgsConstructor
 78	@Builder
 79	@Table(name = "orders")
 80	public class Order extends BaseTimeEntity {
 81	
 82	    @Id
 83	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 84	    private Long id;
 85	
 86	    @ManyToOne(fetch = FetchType.LAZY)
 87	    @JoinColumn(name = "user_id")
 88	    private User user; // 주문자
 89	
 90	    @OneToOne(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
 91	    private Payment payment; // 연관된 결제 정보
 92	
 93	    @OneToOne(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
 94	    private OrderShipment orderShipment; // 구매자 배송 정보
 95	
 96	    private int totalAmount; // 총 금액
 97	    private int discountAmount; // 할인 금액
 98	    private int usedPoints; // 사용된 포인트
 99	
100	    @Enumerated(EnumType.STRING)
101	    private OrderStatus status; // 주문 상태 (결제대기, 결제완료 등)
102	
103	    @OneToOne(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
104	    private WarehouseStorage warehouseStorage; // 창고 보관 정보
105	
106	    @Builder.Default
107	    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
108	    private List<OrderItem> orderItems = new ArrayList<>();
109	
110	    @OneToOne(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
111	    private OrderBid orderBid;
112	
113	    /**
114	     * 주문 항목을 추가합니다.
115	     *
116	     * @param orderItem 주문 항목
117	     */
118	    public void addOrderItem(OrderItem orderItem) {
119	        orderItems.add(orderItem);
120	        orderItem.addOrder(this);
121	    }
122	
123	    /**
124	     * Payment와의 양방향 관계를 설정합니다.
125	     *
126	     * @param payment 결제 정보
127	     */
128	    public void assignPayment(Payment payment) {
129	        this.payment = payment;
130	        if (payment != null && payment.getOrder() != this) {
131	            payment.assignOrder(this);
132	        }
133	    }
134	
135	    /**
136	     * OrderShipment와의 양방향 관계를 설정합니다.
137	     *
138	     * @param orderShipment 배송 정보
139	     */
140	    public void assignOrderShipment(OrderShipment orderShipment) {
141	        this.orderShipment = orderShipment;
142	        if (orderShipment != null && orderShipment.getOrder() != this) {
143	            orderShipment.assignOrder(this);
144	        }
145	    }
146	
147	    /**
148	     * WarehouseStorage와의 양방향 관계를 설정합니다.
149	     *
150	     * @param warehouseStorage 창고 보관 정보
151	     */
152	    public void assignWarehouseStorage(WarehouseStorage warehouseStorage) {
153	        this.warehouseStorage = warehouseStorage;
154	        if (warehouseStorage != null && warehouseStorage.getOrder() != this) {
155	            warehouseStorage.assignOrder(this);
156	        }
157	    }
158	
159	    /**
160	     * 주문 상태를 업데이트합니다.
161	     * 상태 전이 규칙에 따라 유효한 경우에만 상태가 변경됩니다.
162	     *
163	     * @param newStatus 새 주문 상태
164	     * @throws InvalidOrderStatusException 유효하지 않은 상태 전이인 경우
165	     */
166	    public void updateStatus(OrderStatus newStatus) {
167	        if (this.status == null || this.status.canTransitionTo(newStatus)) {
168	            this.status = newStatus;
169	        } else {
170	            throw new InvalidOrderStatusException(
171	                    String.format("상태 전환이 허용되지 않습니다: %s -> %s", this.status, newStatus)
172	            );
173	        }
174	    }
175	
176	    /**
177	     * OrderBid와의 양방향 관계를 설정합니다.
178	     *
179	     * @param orderBid 주문 입찰
180	     */
181	    public void assignOrderBid(OrderBid orderBid) {
182	        this.orderBid = orderBid;
183	        if (orderBid != null && orderBid.getOrder() != this) {
184	            orderBid.assignOrder(this);
185	        }
186	    }
187	}
